{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "It would require physical activity to include unstructured play outside, unless weather conditions make it unreasonable.",
      "rationale": "Conveys the outdoor unstructured-play requirement and its weather exception."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "Physical education classes and time spent using electronic devices would not count as this required physical activity.",
      "rationale": "Conveys the electronic-device exclusion but narrows it to actual use; the bill excludes time during which device use is permitted."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Physical education classes and time spent using electronic devices would not count as this required physical activity.",
      "rationale": "Conveys that physical education class time does not count toward the required physical activity."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "Under this proposal, students could be denied the privilege of participating in physical activity if they violate school discipline policies or engage in violent, threatening, or significantly disruptive behavior. Teachers or administrators would be permitted to remove students from physical activity as a form of discipline",
      "rationale": "Conveys denial and removal authority and several disciplinary grounds, but omits the express school-district policy or code-of-conduct grounds and the requirement that other disruptive or impairing behavior affect other students' participation in and benefits from physical activity."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "Teachers or administrators would be permitted to remove students from physical activity as a form of discipline and may assign them alternative lessons or activities to improve their behavior.",
      "rationale": "Conveys alternative disciplinary work to improve behavior, but does not convey that the alternatives may themselves include physical activities or clearly limit this authority to students removed or denied participation under the specified disciplinary grounds."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The act would take effect immediately upon becoming law.",
      "rationale": "Accurately conveys the effective date."
    }
  ]
}
